tool_calls:
cat > /home/eval/report.sh <<'EOF'
#!/bin/bash
# usage: report.sh INBOX_DIR OUT_FILE
python3 - "$1" "$2" <<'PY'
import sys, os, json
from email.utils import getaddresses
from collections import Counter
d, out = sys.argv[1], sys.argv[2]
cnt = Counter()
names = sorted(n for n in os.listdir(d)
               if n.endswith('.json') and os.path.isfile(os.path.join(d, n)))
for n in names:
    try:
        with open(os.path.join(d, n), 'rb') as f:
            obj = json.loads(f.read().decode('utf-8'))
    except Exception:
        sys.stderr.write('skip: %s\n' % n)
        continue
    if not isinstance(obj, dict):
        continue
    for k in ('to', 'cc'):
        v = obj.get(k)
        if isinstance(v, list):
            v = ', '.join(x for x in v if isinstance(x, str))
        if not isinstance(v, str) or not v.strip():
            continue
        for _, addr in getaddresses([v], strict=False):
            addr = addr.strip()
            if '@' not in addr:
                continue
            dom = addr.rsplit('@', 1)[1].strip().strip('>').lower()
            if dom:
                cnt[dom] += 1
with open(out, 'w') as f:
    for dom, c in sorted(cnt.items(), key=lambda x: (-x[1], x[0])):
        f.write('%d %s\n' % (c, dom))
PY
exit 0
EOF
mkdir -p /out; bash /home/eval/report.sh /data/inbox /out/domains.txt; echo $?; cat /out/domains.txt

